import Foundation
import simd

/// Harbour buildings generated by the stylized-map-renderer skill (`.agents/skills/stylized-map-renderer`),
/// and by nothing else. `tools/skill-buildings/bake_harbour.py` runs the skill's own importer and
/// generators on OSM footprints and writes `harbour_skill_buildings.bin`: every building shell, the
/// skill's instanced module library (windows, doors, shutters, tanks, dishes...) and its instance
/// list. This type only places that output on the app's terrain and hands it to the renderer:
/// shells as unique triangles, modules as GPU instances with the skill's LOD1 form (window pane
/// only, roof props dropped) beyond the renderer's LOD distance.
nonisolated struct DioramaSkillBuildings: Sendable {
    nonisolated struct Module: Sendable {
        let vertexStart: Int, vertexCount: Int, indexStart: Int, indexCount: Int
        let lightStart: Int, lightCount: Int
        let radius: Float
    }

    nonisolated struct Building: Sendable {
        let id: UInt64
        let longitude: Double, latitude: Double
        let height: Float
        let kind: UInt8
        let vertexStart: Int, vertexCount: Int, indexStart: Int, indexCount: Int
        let instanceStart: Int, instanceCount: Int
        let ringStart: Int, ringCount: Int
        let farVertexStart: Int, farVertexCount: Int, farIndexStart: Int, farIndexCount: Int
    }

    /// Which skill output to place: full detail (LOD0 shells + instanced modules) or the coarse
    /// surroundings (the skill's LOD2 shells, no modules).
    enum Detail: Sendable { case full, context }

    /// Measured result of one placement pass.
    nonisolated struct Report: Sendable {
        var buildings = 0
        var shellTriangles = 0
        var moduleTriangles = 0
        var instances = 0
        var litWindows = 0
        var lines: [String] {
            guard buildings > 0 else { return ["Skill buildings: none in this tile"] }
            return ["Skill buildings (stylized-map-renderer): \(buildings) · \(shellTriangles) unique shell tris · \(moduleTriangles) module tris · \(instances) instances · \(litWindows) lit at night"]
        }
    }

    static let resourceName = "harbour_skill_buildings"

    let originLatitude: Double
    let originLongitude: Double
    let modules: [Module]
    let buildings: [Building]
    private let payload: Data
    private let ringOffset: Int
    private let vertexOffset: Int
    private let indexOffset: Int
    private let instanceOffset: Int

    private static let vertexStride = 14
    private static let instanceStride = 24

    /// Loads and inflates the bundled skill output. Nil when missing or malformed.
    static func load() -> DioramaSkillBuildings? {
        guard let url = Bundle.main.url(forResource: resourceName, withExtension: "bin"),
              let file = try? Data(contentsOf: url, options: .mappedIfSafe) else {
            print("[SkillBuildings] \(resourceName).bin missing from the bundle")
            return nil
        }
        return DioramaSkillBuildings(file: file)
    }

    init?(file: Data) {
        guard file.count > 28, file.prefix(4) == Data("SKB2".utf8) else { return nil }
        let header = file.withUnsafeBytes { raw -> (UInt32, Double, Double, UInt32) in
            (raw.loadUnaligned(fromByteOffset: 4, as: UInt32.self), raw.loadUnaligned(fromByteOffset: 8, as: Double.self),
             raw.loadUnaligned(fromByteOffset: 16, as: Double.self), raw.loadUnaligned(fromByteOffset: 24, as: UInt32.self))
        }
        guard header.0 == 2, let inflated = try? (file.subdata(in: 28..<file.count) as NSData).decompressed(using: .zlib) as Data,
              inflated.count == Int(header.3) else {
            print("[SkillBuildings] unreadable payload")
            return nil
        }
        originLatitude = header.1
        originLongitude = header.2
        payload = inflated
        var modules: [Module] = [], buildings: [Building] = []
        var offsets = (ring: 0, vertex: 0, index: 0, instance: 0)
        let valid = inflated.withUnsafeBytes { raw -> Bool in
            func u32(_ o: Int) -> Int { Int(raw.loadUnaligned(fromByteOffset: o, as: UInt32.self)) }
            guard raw.count >= 24 else { return false }
            let moduleCount = u32(0), buildingCount = u32(4), vertexCount = u32(8)
            let indexCount = u32(12), instanceCount = u32(16), ringCount = u32(20)
            var o = 24
            let moduleBytes = moduleCount * 28, buildingBytes = buildingCount * 80
            let expected = o + moduleBytes + buildingBytes + ringCount * 8 + vertexCount * Self.vertexStride
                + indexCount * 2 + instanceCount * Self.instanceStride
            guard expected == raw.count else { return false }
            for _ in 0..<moduleCount {
                modules.append(Module(vertexStart: u32(o), vertexCount: u32(o + 4), indexStart: u32(o + 8), indexCount: u32(o + 12),
                                      lightStart: u32(o + 16), lightCount: u32(o + 20),
                                      radius: raw.loadUnaligned(fromByteOffset: o + 24, as: Float.self)))
                o += 28
            }
            for _ in 0..<buildingCount {
                buildings.append(Building(
                    id: raw.loadUnaligned(fromByteOffset: o, as: UInt64.self),
                    longitude: raw.loadUnaligned(fromByteOffset: o + 8, as: Double.self),
                    latitude: raw.loadUnaligned(fromByteOffset: o + 16, as: Double.self),
                    height: raw.loadUnaligned(fromByteOffset: o + 24, as: Float.self),
                    kind: raw.loadUnaligned(fromByteOffset: o + 28, as: UInt8.self),
                    vertexStart: u32(o + 32), vertexCount: u32(o + 36), indexStart: u32(o + 40), indexCount: u32(o + 44),
                    instanceStart: u32(o + 48), instanceCount: u32(o + 52), ringStart: u32(o + 56), ringCount: u32(o + 60),
                    farVertexStart: u32(o + 64), farVertexCount: u32(o + 68), farIndexStart: u32(o + 72), farIndexCount: u32(o + 76)))
                o += 80
            }
            offsets.ring = o
            offsets.vertex = offsets.ring + ringCount * 8
            offsets.index = offsets.vertex + vertexCount * Self.vertexStride
            offsets.instance = offsets.index + indexCount * 2
            return true
        }
        guard valid else {
            print("[SkillBuildings] payload layout mismatch")
            return nil
        }
        self.modules = modules
        self.buildings = buildings
        ringOffset = offsets.ring
        vertexOffset = offsets.vertex
        indexOffset = offsets.index
        instanceOffset = offsets.instance
    }

    /// Buildings whose footprint centroid lies in `tile`; each building belongs to exactly one tile.
    func buildings(in tile: DioramaTileID) -> [Building] {
        buildings.filter { DioramaTileID(latitude: $0.latitude, longitude: $0.longitude, zoom: tile.z) == tile }
    }

    /// Footprint of `building` in the tile frame of `projection`.
    func ring(of building: Building, projection: DioramaProjection) -> [DV2] {
        let origin = projection.local(longitude: building.longitude, latitude: building.latitude)
        return payload.withUnsafeBytes { raw in
            (0..<building.ringCount).map { k in
                let o = ringOffset + (building.ringStart + k) * 8
                return origin + DV2(Double(raw.loadUnaligned(fromByteOffset: o, as: Float.self)),
                                    Double(raw.loadUnaligned(fromByteOffset: o + 4, as: Float.self)))
            }
        }
    }

    // MARK: Placement

    /// Appends every skill building of the tile to the packed buffers. Shell triangles go into
    /// 60 m `.buildings` bins; at full detail each library module is stored once and placed as
    /// instances, and lit window panes get a `.windowGlow` instance for night.
    func place(in data: DioramaTileData, terrain: DioramaTerrain, config: DioramaConfig, detail: Detail, binSize: Double,
               vertices: inout [BuildingRenderVertex], indices: inout [UInt32], ranges: inout [DioramaRenderLayer.Range],
               groups: inout [DioramaInstanceGroup], allInstances: inout [DioramaInstanceData],
               parts: inout [DioramaTileArtifacts.Part]) -> Report {
        var report = Report()
        let selected = buildings(in: data.tile)
        guard !selected.isEmpty else { return report }
        let features = Dictionary(data.buildings.map { ($0.id, $0) }, uniquingKeysWith: { a, b in a.area >= b.area ? a : b })
        var cells: [Int: [UInt32]] = [:]
        var skirts = DioramaMesh()
        var placements: [Int: [Int: [DioramaInstanceData]]] = [:]
        var glowPlacements: [Int: [Int: [DioramaInstanceData]]] = [:]
        let shellStartIndex = indices.count

        payload.withUnsafeBytes { raw in
            for building in selected {
                let ring = ring(of: building, projection: data.projection)
                guard ring.count >= 3 else { continue }
                let origin = data.projection.local(longitude: building.longitude, latitude: building.latitude)
                // The app's own floor rule (site datum, connected decks); a plinth only where the ground dips.
                let base = features[building.id].map { terrain.buildingHeight($0) } ?? terrain.foundationHeight(ring)
                if DioramaFennKit.needsSkirt(ring, terrain: terrain) {
                    terrain.foundation(DioramaPolygon.counterClockwise(ring), top: base, swatch: .concrete, into: &skirts)
                }
                let offset = SIMD3<Float>(Float(origin.x), Float(origin.y), Float(base))
                let (vStart, vCount, iStart, iCount) = detail == .full
                    ? (building.vertexStart, building.vertexCount, building.indexStart, building.indexCount)
                    : (building.farVertexStart, building.farVertexCount, building.farIndexStart, building.farIndexCount)
                guard vCount > 0, iCount >= 3 else { continue }
                let first = UInt32(vertices.count)
                for k in 0..<vCount {
                    vertices.append(vertex(raw, index: vStart + k, offset: offset))
                }
                for t in stride(from: 0, to: iCount - 2, by: 3) {
                    let a = index(raw, iStart + t), b = index(raw, iStart + t + 1), c = index(raw, iStart + t + 2)
                    guard a < vCount, b < vCount, c < vCount else { continue }
                    var tri = [first + UInt32(a), first + UInt32(b), first + UInt32(c)]
                    wind(&tri, vertices)
                    let p = vertices[Int(tri[0])].position + vertices[Int(tri[1])].position + vertices[Int(tri[2])].position
                    let key = Int(floor(Double(p.x) / (3 * binSize))) + Int(floor(Double(p.y) / (3 * binSize))) * 10000
                    cells[key, default: []].append(contentsOf: tri)
                    report.shellTriangles += 1
                }
                report.buildings += 1
                guard detail == .full else { continue }
                for k in 0..<building.instanceCount {
                    let o = instanceOffset + (building.instanceStart + k) * Self.instanceStride
                    let module = Int(raw.loadUnaligned(fromByteOffset: o, as: UInt16.self))
                    guard module < modules.count else { continue }
                    let lit = raw.loadUnaligned(fromByteOffset: o + 2, as: UInt8.self) != 0
                    let local = SIMD3(raw.loadUnaligned(fromByteOffset: o + 4, as: Float.self),
                                      raw.loadUnaligned(fromByteOffset: o + 8, as: Float.self),
                                      raw.loadUnaligned(fromByteOffset: o + 12, as: Float.self))
                    let yaw = raw.loadUnaligned(fromByteOffset: o + 16, as: Float.self)
                    let scale = raw.loadUnaligned(fromByteOffset: o + 20, as: Float.self)
                    let p = local + offset
                    guard p.x.isFinite, p.y.isFinite, p.z.isFinite, yaw.isFinite, scale.isFinite, scale > 0 else { continue }
                    let instance = DioramaInstanceData(placement: SIMD4(p, yaw),
                        scale: SIMD4(scale, scale, scale, modules[module].radius * scale))
                    let bin = Int(floor(Double(p.x) / binSize)) + Int(floor(Double(p.y) / binSize)) * 10000
                    placements[module, default: [:]][bin, default: []].append(instance)
                    if lit { glowPlacements[module, default: [:]][bin, default: []].append(instance) }
                    report.instances += 1
                }
            }

            for key in cells.keys.sorted() {
                guard let batch = cells[key] else { continue }
                ranges.append(Self.range(.buildings, batch: batch, start: indices.count, vertices: vertices))
                indices.append(contentsOf: batch)
            }
            if !skirts.isEmpty {
                let base = UInt32(vertices.count)
                vertices.append(contentsOf: DioramaMeshPacking.vertices(skirts, category: .buildings, config: config))
                let batch = skirts.indices.map { base + $0 }
                ranges.append(Self.range(.buildings, batch: batch, start: indices.count, vertices: vertices))
                indices.append(contentsOf: batch)
                report.shellTriangles += batch.count / 3
            }

            // Library modules: stored once per tile (full + LOD1 light range), then placed.
            var stored: [Int: (full: Int, fullCount: Int, light: Int, lightCount: Int)] = [:]
            var storedGlow: [Int: (start: Int, count: Int)] = [:]
            func store(_ m: Int) -> (full: Int, fullCount: Int, light: Int, lightCount: Int) {
                if let found = stored[m] { return found }
                let module = modules[m]
                let first = UInt32(vertices.count)
                for k in 0..<module.vertexCount { vertices.append(vertex(raw, index: module.vertexStart + k, offset: .zero)) }
                func lay(_ start: Int, _ count: Int) -> (Int, Int) {
                    let begin = indices.count
                    for t in stride(from: 0, to: count - 2, by: 3) {
                        let a = index(raw, start + t), b = index(raw, start + t + 1), c = index(raw, start + t + 2)
                        guard a < module.vertexCount, b < module.vertexCount, c < module.vertexCount else { continue }
                        var tri = [first + UInt32(a), first + UInt32(b), first + UInt32(c)]
                        if a != b, b != c { wind(&tri, vertices) }
                        indices.append(contentsOf: tri)
                    }
                    return (begin, indices.count - begin)
                }
                let full = lay(module.indexStart, module.indexCount)
                let light = lay(module.lightStart, module.lightCount)
                report.moduleTriangles += full.1 / 3
                let result = (full.0, full.1, light.0, light.1)
                stored[m] = result
                return result
            }
            /// Window glass pushed 1.5 cm proud of the pane as an emissive night prototype.
            func storeGlow(_ m: Int) -> (start: Int, count: Int)? {
                if let found = storedGlow[m] { return found.count > 0 ? found : nil }
                let module = modules[m]
                let first = UInt32(vertices.count)
                var glass: [Bool] = []
                for k in 0..<module.vertexCount {
                    let o = vertexOffset + (module.vertexStart + k) * Self.vertexStride
                    let isGlass = raw.loadUnaligned(fromByteOffset: o + 9, as: UInt8.self) == 1
                    glass.append(isGlass)
                    let source = vertex(raw, index: module.vertexStart + k, offset: .zero)
                    let n = SIMD3(source.normal.x, source.normal.y, source.normal.z)
                    let p = SIMD3(source.position.x, source.position.y, source.position.z) + n * 0.015
                    vertices.append(BuildingRenderVertex(position: SIMD4(p, 1), normal: source.normal,
                        color: SIMD4(1.0, 0.80, 0.52, 1), appearance: SIMD4(0.85, 1, 0, 4)))
                }
                let begin = indices.count
                for t in stride(from: 0, to: module.indexCount - 2, by: 3) {
                    let a = index(raw, module.indexStart + t), b = index(raw, module.indexStart + t + 1), c = index(raw, module.indexStart + t + 2)
                    guard a < module.vertexCount, b < module.vertexCount, c < module.vertexCount,
                          glass[a], glass[b], glass[c] else { continue }
                    var tri = [first + UInt32(a), first + UInt32(b), first + UInt32(c)]
                    wind(&tri, vertices)
                    indices.append(contentsOf: tri)
                }
                let result = (begin, indices.count - begin)
                storedGlow[m] = result
                return result.1 > 0 ? result : nil
            }

            var moduleInstances = 0
            for m in placements.keys.sorted() {
                guard let bins = placements[m] else { continue }
                let r = store(m)
                for bin in bins.keys.sorted() {
                    guard let list = bins[bin], !list.isEmpty else { continue }
                    groups.append(Self.group(.buildings, full: (r.full, r.fullCount), light: (r.light, r.lightCount),
                                             list: list, first: allInstances.count))
                    allInstances.append(contentsOf: list)
                    moduleInstances += list.count
                }
            }
            var glowInstances = 0
            for m in glowPlacements.keys.sorted() {
                guard let bins = glowPlacements[m], let g = storeGlow(m) else { continue }
                for bin in bins.keys.sorted() {
                    guard let list = bins[bin], !list.isEmpty else { continue }
                    groups.append(Self.group(.windowGlow, full: (g.start, g.count), light: (g.start, g.count),
                                             list: list, first: allInstances.count))
                    allInstances.append(contentsOf: list)
                    glowInstances += list.count
                }
            }
            report.litWindows = glowInstances
            parts.append(.init(category: .buildings, triangles: (indices.count - shellStartIndex) / 3, instances: moduleInstances))
            if glowInstances > 0 { parts.append(.init(category: .windowGlow, triangles: 0, instances: glowInstances)) }
        }
        return report
    }

    /// `DioramaBuilt` records for the tile's mapped footprints, so compound walls, amenities, props
    /// and labels keep clear of the skill buildings. No geometry is produced here.
    func footprints(for data: DioramaTileData, roads: DioramaRoadIndex) -> [DioramaBuilt] {
        let heights = Dictionary(buildings.map { ($0.id, Double($0.height)) }, uniquingKeysWith: { a, _ in a })
        return data.buildings.map { f in
            let height = max(heights[f.id] ?? f.height ?? 3.2, 2.8)
            let floors = max(1, Int((height / 3.2).rounded()))
            let commercial = ["commercial", "retail", "shop", "supermarket", "kiosk"].contains(f.type.lowercased())
            let kind: DioramaBuildingKind = floors >= 3 ? .apartments : (commercial ? .commercial : .villa)
            var entrance = f.centroid, entranceOut = DV2(0, -1), best = Double.infinity
            for i in f.ring.indices where !(i < f.clipped.count && f.clipped[i]) {
                let a = f.ring[i], b = f.ring[(i + 1) % f.ring.count]
                guard a.distance(to: b) > 1.5 else { continue }
                let mid = (a + b) * 0.5, out = (b - a).normalized.right
                let distance = roads.nearest(to: mid + out * 0.5, within: 60)?.distance ?? 60
                if distance < best { best = distance; entrance = mid; entranceOut = out }
            }
            return DioramaBuilt(feature: f, kind: kind, floors: floors, height: height,
                                box: DioramaPolygon.minimumAreaRectangle(f.ring), flatRoof: kind != .villa,
                                wallColor: .whitewash, entrance: entrance, entranceOut: entranceOut)
        }
    }

    // MARK: Decoding helpers

    private func index(_ raw: UnsafeRawBufferPointer, _ i: Int) -> Int {
        Int(raw.loadUnaligned(fromByteOffset: indexOffset + i * 2, as: UInt16.self))
    }

    private func vertex(_ raw: UnsafeRawBufferPointer, index i: Int, offset: SIMD3<Float>) -> BuildingRenderVertex {
        let o = vertexOffset + i * Self.vertexStride
        let p = SIMD3<Float>(Float(raw.loadUnaligned(fromByteOffset: o, as: Int16.self)),
                             Float(raw.loadUnaligned(fromByteOffset: o + 2, as: Int16.self)),
                             Float(raw.loadUnaligned(fromByteOffset: o + 4, as: Int16.self))) * 0.01 + offset
        var n = SIMD3<Float>(Float(raw.loadUnaligned(fromByteOffset: o + 6, as: Int8.self)),
                             Float(raw.loadUnaligned(fromByteOffset: o + 7, as: Int8.self)),
                             Float(raw.loadUnaligned(fromByteOffset: o + 8, as: Int8.self)))
        n = simd_length(n) > 0.001 ? simd_normalize(n) : SIMD3(0, 0, 1)
        let glass = raw.loadUnaligned(fromByteOffset: o + 9, as: UInt8.self) == 1
        let ao = Float(raw.loadUnaligned(fromByteOffset: o + 13, as: UInt8.self)) / 255
        let rgb = SIMD3<Float>(Float(raw.loadUnaligned(fromByteOffset: o + 10, as: UInt8.self)),
                               Float(raw.loadUnaligned(fromByteOffset: o + 11, as: UInt8.self)),
                               Float(raw.loadUnaligned(fromByteOffset: o + 12, as: UInt8.self))) / 255 * ao
        // Painted surfaces carry no material code, so no texture, facade or retrofit pass touches
        // them; glass gets the renderer's quiet sky reflection (material 6).
        return BuildingRenderVertex(position: SIMD4(p, 1), normal: SIMD4(n, 0), color: SIMD4(rgb, 1),
                                    appearance: SIMD4(0.85, glass ? 6 : 0, 0, 0))
    }

    /// Winds a triangle counter-clockwise around its vertex normals (the renderer culls back faces).
    private func wind(_ tri: inout [UInt32], _ vertices: [BuildingRenderVertex]) {
        let a = vertices[Int(tri[0])], b = vertices[Int(tri[1])], c = vertices[Int(tri[2])]
        let pa = SIMD3(a.position.x, a.position.y, a.position.z)
        let pb = SIMD3(b.position.x, b.position.y, b.position.z)
        let pc = SIMD3(c.position.x, c.position.y, c.position.z)
        let n = SIMD3(a.normal.x + b.normal.x + c.normal.x, a.normal.y + b.normal.y + c.normal.y, a.normal.z + b.normal.z + c.normal.z)
        if simd_dot(simd_cross(pb - pa, pc - pa), n) < 0 { tri.swapAt(1, 2) }
    }

    private static func range(_ category: DioramaCategory, batch: [UInt32], start: Int, vertices: [BuildingRenderVertex]) -> DioramaRenderLayer.Range {
        var low = SIMD3<Float>(repeating: .greatestFiniteMagnitude), high = -low
        for i in batch {
            let p = vertices[Int(i)].position
            low = simd_min(low, SIMD3(p.x, p.y, p.z)); high = simd_max(high, SIMD3(p.x, p.y, p.z))
        }
        return .init(category: category, start: start, count: batch.count,
                     minimum: low - SIMD3(repeating: 2), maximum: high + SIMD3(repeating: 2), doubleSided: false)
    }

    private static func group(_ category: DioramaCategory, full: (Int, Int), light: (Int, Int),
                              list: [DioramaInstanceData], first: Int) -> DioramaInstanceGroup {
        var low = SIMD3<Float>(repeating: .greatestFiniteMagnitude), high = -low
        for item in list {
            low = simd_min(low, item.centre - SIMD3(repeating: item.radius))
            high = simd_max(high, item.centre + SIMD3(repeating: item.radius))
        }
        return DioramaInstanceGroup(category: category, fullStart: full.0, fullCount: full.1,
                                    lightStart: light.0, lightCount: light.1, doubleSided: false,
                                    instances: list, firstInstance: first, minimum: low, maximum: high)
    }
}
